/** One fresh-schema MySQL replay: real USE, owner fact, concurrency and no quantity mutation. */
@EnabledIfEnvironmentVariable(named="IAS_PART_MYSQL_URL",matches="jdbc:mysql://127\\.0\\.0\\.1:3307/qa_stock_part_[a-z0-9_]+.*")
class FinancePartExecutionMySqlTest {
 @Test void freshMysqlOwnerAndMinimumPrivilegeReplay()throws Exception{
  String url=System.getenv("IAS_PART_MYSQL_URL");var db=new DriverManagerDataSource(url,System.getenv("IAS_PART_MYSQL_USER"),System.getenv("IAS_PART_MYSQL_PASSWORD"));var fixture=new DriverManagerDataSource(url,System.getenv("IAS_PART_MYSQL_FIXTURE_USER"),System.getenv("IAS_PART_MYSQL_FIXTURE_PASSWORD"));String ticket=id(),round=id(),group=id(),completion=id(),quote=id(),line=id(),order=id(),use=id();Actor actor=new Actor(1,10,Set.of(21L));
  exec(fixture,"INSERT INTO stock_warehouse VALUES(11,1,'W',TRUE)");exec(fixture,"INSERT INTO stock_part VALUES(101,1,'P','part','m','pcs',TRUE,0)");exec(fixture,"INSERT INTO stock_balance VALUES(1,11,101,10,0,0)");exec(fixture,"INSERT INTO stock_finance_generation VALUES(1,'"+ticket+"',3,NULL,0)");
  var approval=new StockExecutions.Approval(UUID.fromString(order),1,1,11,ticket,round,id(),10,Instant.now(),"CUSTOMER_PAID",new TreeMap<>(Map.of(101L,2L)));var ledger=new StockExecutions(db,new StockExecutions.Access(){public StockExecutions.Approval authorize(StockExecutions.Actor a,StockExecutions.Command c){return approval;}public void requirePaidCoverage(StockExecutions.Actor a,StockExecutions.Command c,StockExecutions.Approval p){}},java.time.Clock.systemUTC());var stockActor=new StockExecutions.Actor(1,10);ledger.execute(stockActor,new StockExecutions.Command(UUID.randomUUID(),UUID.fromString(order),StockExecutions.Action.RESERVE,0,new TreeMap<>()));ledger.execute(stockActor,new StockExecutions.Command(UUID.randomUUID(),UUID.fromString(order),StockExecutions.Action.ISSUE,1,new TreeMap<>()));ledger.execute(stockActor,new StockExecutions.Command(UUID.fromString(use),UUID.fromString(order),StockExecutions.Action.USE,2,new TreeMap<>(Map.of(101L,2L))));
  FinancePartExecution.Authority authority=new FinancePartExecution.Authority(){public Map<String,Object> permit(Actor a,Command c){return Map.of("tenantId",Long.toString(a.tenantId()),"actorUserId",Long.toString(a.userId()),"operationId",c.value("operationId"),"commandDigest",c.digest(),"ticketId",ticket,"roundId",round,"assignmentId",UUID.randomUUID().toString(),"state","PREPARED","checkedAt",Instant.now().toString());}public Actor current(boolean write){return actor;}public Map<String,Object> completion(long t,long c,String g,String x){var selected=new TreeMap<String,Object>(Map.of("id",line,"ticketId",ticket,"roundId",round,"kind","PART","amountCents","1200"));selected.put("partBinding",new TreeMap<>(Map.of("approvalId",order,"approvalVersion","1","warehouseId","11","partId","101","quantity","2","unitCode","pcs","allocationRule","FULL_LINE_SINGLE_USE_V1")));var lines=List.<Map<String,Object>>of(selected);var out=new LinkedHashMap<String,Object>();out.put("coverageVersion","2");out.put("tenantId","1");out.put("companyId","21");out.put("groupId",group);out.put("completionId",completion);out.put("quoteId",quote);out.put("quoteVersion","2");out.put("generation","3");out.put("ticketId",ticket);out.put("roundId",round);out.put("coverageDigest",sha(lines));out.put("lines",lines);out.put("checkedAt",Instant.now().toString());return out;}public OrderFact order(Actor a,String o,long w){return new OrderFact(1,11,ticket,round,order,10,new TreeMap<>(Map.of(101L,2L)));}};var store=new FinancePartExecutionStore(db,authority);
  java.util.function.Function<String,Command> command=operation->new Command(new LinkedHashMap<>(Map.ofEntries(Map.entry("operationId",operation),Map.entry("groupId",group),Map.entry("completionId",completion),Map.entry("quoteId",quote),Map.entry("quoteVersion","2"),Map.entry("generation","3"),Map.entry("lineId",line),Map.entry("orderId",order),Map.entry("useOperationId",use),Map.entry("partId","101"),Map.entry("quantity","2"),Map.entry("amountCents","1200"),Map.entry("warehouseId","11"),Map.entry("companyId","21"))));
  var refused=command.apply(id());assertEquals("PROVEN_NO_EXECUTION",store.refuse(1,refused.value("operationId"),refused.digest()).get("state"));
  assertEquals("PART_EXECUTION_PERMANENTLY_REJECTED",assertThrows(com.ias.trust.Problem.class,()->store.execute(refused)).code);
  assertEquals("PROVEN_NO_EXECUTION",new FinancePartExecutionStore(db,null).ownerResult(1,refused.value("operationId"),refused.digest()).get("state"));
  assertEquals(0,count(db,"stock_finance_part_execution"));assertThrows(SQLException.class,()->exec(db,"DELETE FROM stock_part_execution_gate"));assertThrows(SQLException.class,()->exec(db,"UPDATE stock_part_execution_gate SET command_digest='changed'"));
  String original=id();exec(fixture,"ALTER TABLE stock_finance_part_audit ADD CONSTRAINT qa_fail_part_audit CHECK(actor_user_id<>10)");assertThrows(RuntimeException.class,()->store.execute(command.apply(original)));assertEquals(0,count(db,"stock_finance_part_execution"));assertEquals(0,count(db,"stock_finance_part_operation"));exec(fixture,"ALTER TABLE stock_finance_part_audit DROP CONSTRAINT qa_fail_part_audit");var executed=store.execute(command.apply(original));assertEquals("EXECUTED",executed.get("state"));assertEquals("COMMITTED",store.refuse(1,original,command.apply(original).digest()).get("state"));assertEquals("EXECUTED",store.execute(command.apply(original)).get("state"));assertEquals(1,count(db,"stock_finance_part_execution"));assertEquals(1,count(db,"stock_part_fee_notification_outbox"));var jdbc=new org.springframework.jdbc.core.JdbcTemplate(db);var tx=new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(db));new StockPartFeeNotificationDelivery(jdbc,tx,e->{throw new IllegalStateException("DOWN");}).tick();assertEquals("PENDING",jdbc.queryForObject("SELECT delivery_state FROM stock_part_fee_notification_outbox WHERE event_id=?",String.class,original));jdbc.update("UPDATE stock_part_fee_notification_outbox SET next_attempt_at=TIMESTAMPADD(SECOND,-1,CURRENT_TIMESTAMP(3)) WHERE event_id=?",original);new StockPartFeeNotificationDelivery(jdbc,tx,e->Map.of("eventId",e.get("eventId"),"ack","COMMITTED_DUPLICATE")).tick();assertEquals("DELIVERED",jdbc.queryForObject("SELECT delivery_state FROM stock_part_fee_notification_outbox WHERE event_id=?",String.class,original));var context=new LinkedHashMap<String,Object>();context.put("eventId",original);context.put("tenantId","1");context.put("eventType","inventory.consumed");context.put("companyId","21");context.put("ticketId",ticket);context.put("roundId",round);context.put("feeGroupId",group);context.put("generation","3");context.put("executionReceiptId",executed.get("executionReceiptId"));context.put("lineId",line);context.put("warehouseId","11");context.put("partId","101");context.put("quantity","2");context.put("amountCents","1200");context.put("purpose","DELIVERY");var request=new MockHttpServletRequest();request.setSecure(true);request.setAttribute("ias.chain.edge","notification-stock");try(var chain=mockStatic(Chain.class,CALLS_REAL_METHODS)){chain.when(Chain::active).thenReturn(true);chain.when(Chain::role).thenReturn("stock");var controller=new PartFeeNotificationContextController(db);assertEquals(true,controller.context(context,request).get("currentScope"));var altered=new LinkedHashMap<>(context);altered.put("quantity","3");assertEquals(409,assertThrows(com.ias.trust.Problem.class,()->controller.context(altered,request)).status);exec(fixture,"UPDATE stock_finance_generation SET generation=4 WHERE tenant_id=1 AND ticket_id='"+ticket+"'");assertEquals(409,assertThrows(com.ias.trust.Problem.class,()->controller.context(context,request)).status);exec(fixture,"UPDATE stock_finance_generation SET generation=3 WHERE tenant_id=1 AND ticket_id='"+ticket+"'");}assertEquals(8,scalar(db,"SELECT on_hand FROM stock_balance WHERE tenant_id=1 AND warehouse_id=11 AND part_id=101"));assertEquals(0,scalar(db,"SELECT reserved FROM stock_balance WHERE tenant_id=1 AND warehouse_id=11 AND part_id=101"));
  try(var pool=Executors.newFixedThreadPool(4)){var calls=new ArrayList<Callable<Boolean>>();for(int i=0;i<4;i++)calls.add(()->{try{store.execute(command.apply(id()));return true;}catch(RuntimeException expected){return false;}});long extra=0;for(var f:pool.invokeAll(calls))if(f.get())extra++;assertEquals(0,extra);}assertEquals(1,count(db,"stock_finance_part_execution"));assertThrows(SQLException.class,()->exec(db,"UPDATE stock_finance_part_execution SET amount_cents=1"));assertThrows(SQLException.class,()->exec(db,"DELETE FROM stock_finance_part_execution"));
 }
 static void exec(javax.sql.DataSource db,String sql)throws SQLException{try(var c=db.getConnection();var s=c.createStatement()){s.execute(sql);}}
 static long count(javax.sql.DataSource db,String table)throws SQLException{return scalar(db,"SELECT COUNT(*) FROM "+table);}
 static long scalar(javax.sql.DataSource db,String sql)throws SQLException{try(var c=db.getConnection();var s=c.createStatement();var r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
 static String id(){return UUID.randomUUID().toString();}
}
